// ABI contract for hybrid handoff state: magic/version, layout, roundtrip.

#include "hybrid/state_abi.h"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <cstdint>
#include <cstring>
#include <type_traits>

TEST_CASE("magic and version are stable wire constants")
{
  CHECK(HYBRID_STATE_MAGIC == 0x42594841u);
  // v6 appends write_mask[2] after the v5 l2c block (carved from reserved,
  // total size unchanged); v5 appended struct hybrid_l2c after the v4 m_ext
  // block. Readers reject older files by magic+version+size.
  CHECK(HYBRID_STATE_VERSION == 6u);
}

TEST_CASE("struct is standard-layout, trivially copyable, no tail padding")
{
  CHECK(std::is_standard_layout_v<hybrid_state_v1>);
  CHECK(std::is_trivially_copyable_v<hybrid_state_v1>);
  CHECK(sizeof(hybrid_state_v1) % 8 == 0);
}

TEST_CASE("header field offsets")
{
  CHECK(offsetof(hybrid_state_v1, magic) == 0);
  CHECK(offsetof(hybrid_state_v1, version) == 4);
  CHECK(offsetof(hybrid_state_v1, flags) == 8);
  CHECK(offsetof(hybrid_state_v1, hart_id) == 12);
  CHECK(offsetof(hybrid_state_v1, pc) == 16);
  CHECK(offsetof(hybrid_state_v1, priv) == 24);
}

TEST_CASE("GPR and FPR are 32 * uint64_t each, contiguous")
{
  hybrid_state_v1 s{};
  CHECK(offsetof(hybrid_state_v1, gpr) == 32);
  CHECK(sizeof(s.gpr) == 32 * sizeof(uint64_t));
  CHECK(offsetof(hybrid_state_v1, fpr) == 32 + 32 * 8);
  CHECK(sizeof(s.fpr) == 32 * sizeof(uint64_t));
}

TEST_CASE("V-extension fields use compile-time MAX_VLEN constant")
{
  hybrid_state_v1 s{};
  CHECK(HYBRID_VLEN_BYTES_MAX >= 16);  // RVV minimum VLEN=128 -> 16 bytes
  CHECK((HYBRID_VLEN_BYTES_MAX & (HYBRID_VLEN_BYTES_MAX - 1)) == 0);  // power of 2
  CHECK(sizeof(s.vreg) == 32u * HYBRID_VLEN_BYTES_MAX);
}

TEST_CASE("L11: wire format carries VLEN up to 1024 bits (vlenb 128)")
{
  hybrid_state_v1 s{};
  CHECK(HYBRID_VLEN_BYTES_MAX == 128);
  CHECK(sizeof(s.vreg) == 32u * 128u);
  // vreg@1320 + 32*128 data + trailer: 48 (vxsat/vxrm/vcsr/fcsr/mcache_ctl/
  // mmisc_ctl) + 248 (struct hybrid_andes_csr, v3) + 408 (struct
  // hybrid_m_ext_csr, v4) + 1320 (struct hybrid_l2c, v5) + 64 (reserved).
  CHECK(sizeof(hybrid_state_v1)
        == 1320u + 32u * 128u + 48u + sizeof(hybrid_andes_csr)
             + sizeof(hybrid_m_ext_csr) + sizeof(hybrid_l2c) + 64u);
}

TEST_CASE("V CSRs vxsat/vxrm/vcsr follow vreg")
{
  CHECK(offsetof(hybrid_state_v1, vxsat)
        == offsetof(hybrid_state_v1, vreg) + 32u * HYBRID_VLEN_BYTES_MAX);
  CHECK(offsetof(hybrid_state_v1, vxrm)
        == offsetof(hybrid_state_v1, vxsat) + sizeof(uint64_t));
  CHECK(offsetof(hybrid_state_v1, vcsr)
        == offsetof(hybrid_state_v1, vxrm) + sizeof(uint64_t));
}

TEST_CASE("L20: fcsr follows vcsr")
{
  CHECK(offsetof(hybrid_state_v1, fcsr)
        == offsetof(hybrid_state_v1, vcsr) + sizeof(uint64_t));
}

TEST_CASE("Andes setup CSRs (mcache_ctl/mmisc_ctl) follow fcsr, before andes block")
{
  CHECK(offsetof(hybrid_state_v1, mcache_ctl)
        == offsetof(hybrid_state_v1, fcsr) + sizeof(uint64_t));
  CHECK(offsetof(hybrid_state_v1, mmisc_ctl)
        == offsetof(hybrid_state_v1, mcache_ctl) + sizeof(uint64_t));
}

TEST_CASE("v3: struct hybrid_andes_csr follows mmisc_ctl; v4: hybrid_m_ext_csr "
          "follows it, before reserved")
{
  CHECK(HYBRID_FLAG_ANDES == (1u << 3));
  CHECK(HYBRID_FLAG_M_EXT == (1u << 4));
  CHECK(offsetof(hybrid_state_v1, andes)
        == offsetof(hybrid_state_v1, mmisc_ctl) + sizeof(uint64_t));
  CHECK(offsetof(hybrid_state_v1, m_ext)
        == offsetof(hybrid_state_v1, andes) + sizeof(hybrid_andes_csr));
  // v5: the L2C MMIO block follows m_ext; v6: write_mask[2] follows l2c
  // (carved from reserved), reserved follows write_mask.
  CHECK(offsetof(hybrid_state_v1, l2c)
        == offsetof(hybrid_state_v1, m_ext) + sizeof(hybrid_m_ext_csr));
  CHECK(offsetof(hybrid_state_v1, write_mask)
        == offsetof(hybrid_state_v1, l2c) + sizeof(hybrid_l2c));
  CHECK(offsetof(hybrid_state_v1, reserved)
        == offsetof(hybrid_state_v1, write_mask) + 2 * sizeof(uint64_t));
  // 13 scalar CSRs + pmacfg[2] + pmaaddr[16] = 31 * uint64_t.
  CHECK(sizeof(hybrid_andes_csr) == 31u * sizeof(uint64_t));
  // v4: 51 M-mode CSRs = 51 * uint64_t.
  CHECK(sizeof(hybrid_m_ext_csr) == 51u * sizeof(uint64_t));
}

TEST_CASE("v6: write_mask carries one bit per mask-governed config CSR")
{
  CHECK(HYBRID_FLAG_WRITE_MASK == (1u << 6));
  // 13 Andes scalars + 2 pmacfg + 16 pmaaddr + 51 M-ext + mcache_ctl +
  // mmisc_ctl = 84 slots inside the 128-bit mask.
  CHECK(HYBRID_WM_SLOT_COUNT == 84);
  hybrid_state_v1 s{};
  CHECK(sizeof(s.write_mask) == 16u);
  // reserved shrank 64 -> 48 so the v6 total size equals v5's.
  CHECK(sizeof(s.reserved) == 48u);
}

TEST_CASE("v5: struct hybrid_l2c is the 0x0000..0x0527 L2C MMIO register window")
{
  CHECK(HYBRID_FLAG_L2C == (1u << 5));
  // 0x0000..0x0527 inclusive = 1320 bytes = 165 * uint64_t.
  CHECK(sizeof(hybrid_l2c) == 1320u);
  CHECK(HYBRID_L2C_REG_WINDOW_BYTES == 1320u);
  CHECK(HYBRID_L2C_REG_WINDOW_QWORDS == 165u);
  // Writable config register offsets restored on resume.
  CHECK(HYBRID_L2C_OFF_CONTROL == 0x0008u);
  CHECK(HYBRID_L2C_OFF_HPM_CTL0 == 0x0010u);
  CHECK(HYBRID_L2C_OFF_WAYMASK0 == 0x0300u);
}

TEST_CASE("v3: Andes block field layout is locked")
{
  hybrid_state_v1 s{};
  // First scalar at offset 0; the PMA arrays close the block.
  CHECK(offsetof(hybrid_andes_csr, mxstatus) == 0);
  CHECK(sizeof(s.andes.pmacfg) == 2u * sizeof(uint64_t));   // 0xBC0, 0xBC2
  CHECK(sizeof(s.andes.pmaaddr) == 16u * sizeof(uint64_t)); // 0xBD0..0xBDF
  // A few representative scalars carry their CSR mnemonics as named members.
  s.andes.uitb = 0x800;       // CoDense table base
  s.andes.jvt = 0x017;        // Zcmt jump table
  s.andes.ucode = 1;          // DSP overflow flag
  s.andes.mxstatus = 0x40;    // Andes mstatus companion
  CHECK(s.andes.uitb + s.andes.jvt + s.andes.ucode + s.andes.mxstatus
        == 0x800 + 0x017 + 1 + 0x40);
}

TEST_CASE("PMP arrays are sized per spec")
{
  hybrid_state_v1 s{};
  CHECK(sizeof(s.pmpcfg) == HYBRID_PMP_CFG_NUM * sizeof(uint64_t));
  CHECK(sizeof(s.pmpaddr) == HYBRID_PMP_ADDR_NUM * sizeof(uint64_t));
  CHECK(HYBRID_PMP_ADDR_NUM == 64);
  CHECK(HYBRID_PMP_CFG_NUM == 16);
}

TEST_CASE("trailing reserved padding leaves room for future growth")
{
  hybrid_state_v1 s{};
  // 256 bytes were originally reserved; vxsat/vxrm/vcsr consumed 24, and v6
  // carved 16 for write_mask[2] -- all without changing the total struct
  // size. The remainder must still hold a few more uint64 slots before a
  // size-growing version is required.
  CHECK(sizeof(s.reserved) >= 48);
  CHECK(sizeof(s.reserved) % 8 == 0);
}

TEST_CASE("byte-level roundtrip via memcpy preserves all fields")
{
  hybrid_state_v1 src{};
  src.magic = HYBRID_STATE_MAGIC;
  src.version = HYBRID_STATE_VERSION;
  src.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
  src.hart_id = 1;
  src.pc = 0x80001234ULL;
  src.priv = 3;  // M-mode

  for (int i = 0; i < 32; ++i) {
    src.gpr[i] = 0xCAFE0000ULL + i;
    src.fpr[i] = 0xF00D0000ULL + i;
  }
  src.mstatus = 0xa00040080ULL;
  src.mepc    = 0x80002000ULL;
  src.mtvec   = 0x80000000ULL;
  src.satp    = 0x8000000000080000ULL;
  src.vstart  = 0;
  src.vtype   = 0xc0;
  src.vl      = 4;
  src.vlenb   = 16;
  src.vxsat   = 1;
  src.vxrm    = 2;
  src.vcsr    = 0x5;  // vxrm[2:1] | vxsat[0]
  for (size_t i = 0; i < sizeof(src.vreg); ++i) src.vreg[i] = (uint8_t) i;

  alignas(hybrid_state_v1) unsigned char buf[sizeof(hybrid_state_v1)];
  std::memcpy(buf, &src, sizeof(src));
  hybrid_state_v1 dst{};
  std::memcpy(&dst, buf, sizeof(dst));

  CHECK(dst.magic == HYBRID_STATE_MAGIC);
  CHECK(dst.version == HYBRID_STATE_VERSION);
  CHECK(dst.flags == src.flags);
  CHECK(dst.hart_id == 1);
  CHECK(dst.pc == 0x80001234ULL);
  CHECK(dst.priv == 3);
  for (int i = 0; i < 32; ++i) {
    CHECK(dst.gpr[i] == 0xCAFE0000ULL + i);
    CHECK(dst.fpr[i] == 0xF00D0000ULL + i);
  }
  CHECK(dst.mstatus == 0xa00040080ULL);
  CHECK(dst.mepc == 0x80002000ULL);
  CHECK(dst.mtvec == 0x80000000ULL);
  CHECK(dst.satp == 0x8000000000080000ULL);
  CHECK(dst.vtype == 0xc0);
  CHECK(dst.vl == 4);
  CHECK(dst.vlenb == 16);
  CHECK(dst.vxsat == 1);
  CHECK(dst.vxrm == 2);
  CHECK(dst.vcsr == 0x5);
  CHECK(std::memcmp(dst.vreg, src.vreg, sizeof(src.vreg)) == 0);
}

TEST_CASE("flag bits are stable wire constants")
{
  CHECK(HYBRID_FLAG_RV64  == (1u << 0));
  CHECK(HYBRID_FLAG_FP    == (1u << 1));
  CHECK(HYBRID_FLAG_V     == (1u << 2));
  CHECK(HYBRID_FLAG_ANDES == (1u << 3));  // v3: Andes CSR block live
}

